solution.Solution.cs:
public class RingBuffer<T>
{
    private readonly T[] _items;
    private int _start;

    public RingBuffer(int capacity)
    {
        ArgumentOutOfRangeException.ThrowIfLessThan(capacity, 1);
        _items = new T[capacity];
    }

    public int Count { get; private set; }
    public bool IsFull => Count == _items.Length;

    public void Add(T item)
    {
        if (IsFull)
        {
            _items[_start] = item;
            _start = (_start + 1) % _items.Length;
        }
        else
        {
            _items[(_start + Count) % _items.Length] = item;
            Count++;
        }
    }

    public T this[int index]
    {
        get
        {
            if (index < 0 || index >= Count) throw new ArgumentOutOfRangeException(nameof(index));
            return _items[(_start + index) % _items.Length];
        }
    }

    public List<T> ToList()
    {
        var list = new List<T>(Count);
        for (int i = 0; i < Count; i++) list.Add(this[i]);
        return list;
    }
}

public static class Generic
{
    public static T Clamp<T>(T value, T min, T max) where T : IComparable<T>
    {
        if (value.CompareTo(min) < 0) return min;
        if (value.CompareTo(max) > 0) return max;
        return value;
    }

    public static (T Min, T Max) MinMax<T>(IEnumerable<T> items) where T : IComparable<T>
    {
        using var e = items.GetEnumerator();
        if (!e.MoveNext()) throw new InvalidOperationException("no items");
        T min = e.Current, max = e.Current;
        while (e.MoveNext())
        {
            if (e.Current.CompareTo(min) < 0) min = e.Current;
            if (e.Current.CompareTo(max) > 0) max = e.Current;
        }
        return (min, max);
    }

    public static TValue GetOrCreate<TKey, TValue>(Dictionary<TKey, TValue> map, TKey key)
        where TKey : notnull where TValue : new()
    {
        if (!map.TryGetValue(key, out var value))
        {
            value = new TValue();
            map[key] = value;
        }
        return value;
    }
}

unitTests:
Test("ring buffer fills and wraps", () =>
{
    var rb = new RingBuffer<int>(3);
    rb.Add(1); rb.Add(2);
    CheckEq(rb.Count, 2);
    CheckEq(rb.IsFull, false);
    rb.Add(3); rb.Add(4); rb.Add(5);
    CheckEq(rb.IsFull, true);
    CheckEq(rb.ToList(), new[] { 3, 4, 5 });
    CheckEq(rb[0], 3);
    CheckEq(rb[2], 5);
    CheckThrows<ArgumentOutOfRangeException>(() => _ = rb[3]);
});

Test("ring buffer of strings and bad capacity", () =>
{
    var rb = new RingBuffer<string>(1);
    rb.Add("a"); rb.Add("b");
    CheckEq(rb.ToList(), new[] { "b" });
    CheckThrows<ArgumentOutOfRangeException>(() => new RingBuffer<int>(0));
    CheckEq(new RingBuffer<double>(2).ToList().Count, 0);
});

Test("clamp for any comparable type", () =>
{
    CheckEq(Generic.Clamp(15, 0, 10), 10);
    CheckEq(Generic.Clamp(-2.5, 0.0, 1.0), 0.0);
    CheckEq(Generic.Clamp("m", "a", "f"), "f");
    CheckEq(Generic.Clamp(new DateOnly(2026, 5, 1), new DateOnly(2026, 1, 1), new DateOnly(2026, 12, 31)), new DateOnly(2026, 5, 1));
});

Test("min and max", () =>
{
    CheckEq(Generic.MinMax(new[] { 4, 9, 1, 7 }), (1, 9));
    CheckEq(Generic.MinMax(new List<string> { "pear", "apple", "fig" }), ("apple", "pear"));
    CheckThrows<InvalidOperationException>(() => Generic.MinMax(new int[0]));
});

Test("get or create", () =>
{
    var groups = new Dictionary<string, List<int>>();
    Generic.GetOrCreate(groups, "odd").Add(1);
    Generic.GetOrCreate(groups, "odd").Add(3);
    Generic.GetOrCreate(groups, "even").Add(2);
    CheckEq(groups["odd"], new[] { 1, 3 });
    CheckEq(groups.Count, 2);
});

